def sign_changes(pnl):
    count, last = 0, 0
    for x in pnl:
        if x == 0:
            continue
        if last != 0 and (x > 0) != (last > 0):
            count += 1
        last = x
    return count

def modal_prices(prices):
    counts = {}
    for p in prices:
        counts[p] = counts.get(p, 0) + 1
    if not counts:
        return []
    top = max(counts.values())
    return sorted((p for p in counts if counts[p] == top), reverse=True)

def to_pence(text):
    s = text.strip()
    sign = 1
    if s.startswith("-"):
        sign, s = -1, s[1:]
    s = s.replace("£", "").replace(",", "")
    pounds, _, pence = s.partition(".")
    return sign * (int(pounds or "0") * 100 + int((pence + "00")[:2]))

def lot_round(qty, lot):
    lots = abs(qty) // lot
    return lots * lot if qty >= 0 else -lots * lot

def parse_fix(msg):
    out = {}
    if not msg:
        return out
    for field in msg.split(";"):
        tag, _, value = field.partition("=")
        out[int(tag)] = value
    return out

